`timescale 1ns/1ps
// @latency 1
module counter8_core (
    input wire clk,
    input wire rst,
    input wire enable,
    output wire [7:0] count
);

reg [7:0] count_reg;

assign count = count_reg;

always @(posedge clk) begin
    if (rst)
        count_reg <= 8'b0;
    else if (enable)
        count_reg <= count_reg + 8'b1;
end

endmodule
`timescale 1ns/1ps
// @latency 1
// Inherited fixed logical latency from transparent typed child wiring; not measured timing.
module counter8 (
    input wire clk,
    input wire rst,
    input wire enable,
    output wire [7:0] count
);
    counter8_core u_counter8_core (
        .clk(clk),
        .rst(rst),
        .enable(enable),
        .count(count)
    );
endmodule

testbench.text:
`timescale 1ns/1ps
module counter8_tb;
    reg clk = 0;
    reg rst = 1;
    reg enable = 0;
    wire [7:0] count;
    reg [7:0] expected = 0;
    integer errors = 0;
    integer i;
    counter8 dut(.clk(clk), .rst(rst), .enable(enable), .count(count));
    always #5 clk = ~clk;
    initial begin
        for (i = 0; i < 700; i = i + 1) begin
            @(negedge clk);
            rst = (i < 3) || (i == 420);
            enable = (i == 420) || (i < 310) || (i % 7 != 0);
            // Reset priority is tested with enable high after a nonzero state.
            if (i == 420 && expected == 0) begin
                errors = errors + 1;
                $display("FAIL reset-priority coverage requires nonzero count");
            end
            #1;
            if (count !== expected) begin
                errors = errors + 1;
                if (errors <= 8) $display("FAIL cycle=%0d count changed before rising clock edge", i);
            end
            @(posedge clk);
            if (rst) expected = 0;
            else if (enable) expected = expected + 1;
            #1;
            if (count !== expected) begin
                errors = errors + 1;
                if (errors <= 8) $display("FAIL cycle=%0d expected=%0d got=%0d", i, expected, count);
            end
        end
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
    initial begin
        #10000;
        $display("TEST FAILED: watchdog");
        $finish;
    end
endmodule
